export async function listTools() {
  return [
    {
      name: 'inventory_search',
      description: 'Search inventory products by name. Returns matching products, limited by the optional limit argument.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Search string matched case-insensitively against product names.' },
          limit: { type: 'integer', minimum: 1, maximum: 10, description: 'Maximum number of results to return (1-10). Defaults to 10.' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (typeof args !== 'object' || args === null || Array.isArray(args)) {
    throw new Error('Invalid arguments: expected an object');
  }
  const { query, limit = 10 } = args;
  if (typeof query !== 'string') {
    throw new Error('Invalid argument "query": expected a string');
  }
  if (limit !== undefined && (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1 || limit > 10)) {
    throw new Error('Invalid argument "limit": expected an integer between 1 and 10');
  }
  const needle = query.toLowerCase();
  const matches = products.filter(p => p.name.toLowerCase().includes(needle));
  const results = matches.slice(0, limit);
  const text = results.map(p => `${p.id}: ${p.name}`).join('\n');
  return {
    content: [{ type: 'text', text: results.length ? text : 'No matching products found.' }]
  };
}
